// packages/shared/src/memory.ts
var AFFINITY_STAGES = [
  { key: "stranger", min: 0 },
  { key: "acquaintance", min: 10 },
  { key: "familiar", min: 30 },
  { key: "close", min: 60 },
  { key: "fond", min: 100 },
  { key: "beloved", min: 180 }
];
function affinityStageOf(score) {
  let stage = 0;
  for (let index3 = 0; index3 < AFFINITY_STAGES.length; index3 += 1) {
    if (score >= AFFINITY_STAGES[index3].min) stage = index3;
  }
  const next = AFFINITY_STAGES[stage + 1];
  return {
    stage,
    key: AFFINITY_STAGES[stage].key,
    nextAt: next ? next.min : null
  };
}

