function configRoutes(cfg2, db2) {
  const app2 = new Hono2();
  app2.get("/config/:userId", async (c) => {
    const stored = await db2.getUserConfig(c.req.param("userId"));
    const merged = {
      ...defaultUserConfig(cfg2),
      ...stored ?? {}
    };
    const effectiveKey = merged.provider.apiKey || cfg2.llm.apiKey;
    const keyStatus = !effectiveKey ? "none" : merged.provider.apiKey ? "custom" : "default";
    return c.json({
      config: { ...merged, provider: { ...merged.provider, apiKey: maskKey(effectiveKey) } },
      keyStatus
    });
  });
  app2.put("/config/:userId", async (c) => {
    const body = await c.req.json().catch(() => null);
    if (!body?.config || typeof body.config !== "object") {
      return c.json({ error: "config \u5FC5\u586B" }, 400);
    }
    const config = body.config;
    const stored = await db2.getUserConfig(c.req.param("userId"));
    const merged = {
      ...defaultUserConfig(cfg2),
      ...stored ?? {},
      ...config,
      provider: {
        ...defaultUserConfig(cfg2).provider,
        ...stored?.provider ?? {},
        ...config.provider ?? {},
        // apiKey 留空 = 不修改（表单不回填密钥，防止被掩码值覆盖）
        apiKey: config.provider?.apiKey?.trim() ? config.provider.apiKey : stored?.provider?.apiKey ?? ""
      }
    };
    await db2.setUserConfig(c.req.param("userId"), merged);
    return c.json({
      config: { ...merged, provider: { ...merged.provider, apiKey: maskKey(merged.provider.apiKey) } }
    });
  });
  return app2;
}

