      series: [...series.values()],
      channels: [...channelMap.entries()].map(([channel, count]) => ({ channel, count })).sort((a, b) => b.count - a.count),
      models: [...modelMap.values()].sort((a, b) => b.tokens - a.tokens).slice(0, 6),
      providers: [...providerMap.values()].sort((a, b) => b.tokens - a.tokens || b.turns - a.turns).slice(0, 6),
      tools: [...toolMap.entries()].map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count).slice(0, 8),
      plugins: { total: plugins.length, enabled: plugins.filter((p) => p.enabled).length, byKind },
      memories: memoryCount,
