// services/brain/src/routes/voice.ts
function voiceRoutes(cfg2, db2) {
  const app2 = new Hono2();
  app2.post("/voice", async (c) => {
    const body = await c.req.json().catch(() => null);
    const userId = typeof body?.userId === "string" ? body.userId : "";
    const sessionId = typeof body?.sessionId === "string" ? body.sessionId : "";
    const text = typeof body?.text === "string" ? body.text.trim() : "";
    if (!userId || !sessionId || !text) {
      return c.json({ error: "userId/sessionId/text \u5FC5\u586B" }, 400);
    }
    const frames = framesOf(userId);
    const ttsConfig = {
      apiKey: cfg2.fish.apiKey,
      voice: cfg2.fish.voice,
      model: cfg2.fish.model,
      endpoint: cfg2.fish.endpoint,
      sampleRate: cfg2.fish.sampleRate,
      proxy: cfg2.fish.proxy
    };
    return sseResponse(
      async function* (signal) {
        const startedAt = Date.now();
        let cnFull = "";
        let jpFull = "";
        const usage = { input: 0, output: 0, total: 0 };
        try {
          const stream3 = runVoiceTurn(
            { cfg: cfg2, db: db2, userId, sessionId, channel: "desktop", mode: "voice", content: text, frames },
            signal,
            ttsConfig,
            (turnUsage) => {
              usage.input += turnUsage.input;
              usage.output += turnUsage.output;
              usage.total += turnUsage.total;
            }
          );
          for (; ; ) {
            const r = await stream3.next();
            if (r.done) {
              cnFull = r.value.cn;
              jpFull = r.value.jp;
              break;
            }
            yield r.value;
          }
        } catch (error) {
          if (signal.aborted) return;
          const message = error instanceof Error ? error.message : String(error);
          console.error("[voice] \u8BED\u97F3\u56DE\u5408\u5931\u8D25\uFF1A", message);
          yield { type: "error", message };
          return;
        }
        if (!cnFull) {
          yield { type: "error", message: "LLM \u672A\u4EA7\u51FA\u6709\u6548\u56DE\u590D" };
          return;
        }
        const target = await resolveTarget(cfg2, db2, userId);
        const messageId = await finishTurn(db2, {
          sessionId,
          userId,
          channel: "desktop",
          mode: "voice",
          content: cnFull,
          ttsText: jpFull || null,
          target,
          userText: text
        });
        await recordTurnMetric(db2, {
          sessionId,
          userId,
          channel: "desktop",
          startedAt,
          model: target.model,
          providerName: target.providerName,
          usage,
          toolCalls: 0,
          toolNames: []
        });
        yield { type: "done", sessionId, messageId };
      },
      c.req.raw.signal
    );
  });
  return app2;
}

